# Z2712 / Z2713 / Z2589 on N = 4Cp+1 (p ≡ 1 mod 4 prime, p < 2e5, C = 1..30), prime factors ℓ of N, residues mod 4C.
#  SP  : -1 is a subset product of DISTINCT prime factors' residues (mod 4C) (empty product excluded)
#  GEN : -1 in the subgroup generated by the residues
#  Z2589: exact distribution over sign patterns eps_l in {-1,0,1}: P(prod l^eps ≡ -1) (DP over the unit group), vs 1/phi(4C)
import sys, math, time; sys.path.insert(0,'scripts')
import numpy as np
from collections import Counter, defaultdict
X=200000; CMAX=30
N=4*CMAX*X+1
spf=np.zeros(N+1,dtype=np.int32)
for i in range(2,int(N**0.5)+1):
    if spf[i]==0:
        idx=np.arange(i*i,N+1,i); m=spf[idx]==0; spf[idx[m]]=i
primes=[p for p in range(5,X+1,4) if spf[p]==0 and all(p%d for d in range(2,int(p**0.5)+1))]
print("primes",len(primes))
def factor(n):
    out=[]
    while n>1:
        q=int(spf[n]) or n
        out.append(q)
        while n%q==0: n//=q
    return out
def units(m): return [a for a in range(1,m) if math.gcd(a,m)==1]
def gen_closure(res,m):
    S={1%m}; frontier=[1%m]
    while frontier:
        nf=[]
        for s in frontier:
            for r in res:
                t=(s*r)%m
                if t not in S: S.add(t); nf.append(t)
        frontier=nf
    return S
t0=time.time()
stats={}
for C in range(1,CMAX+1):
    m=4*C
    U=units(m); idx={u:i for i,u in enumerate(U)}
    cnt=Counter(); omegas=defaultdict(lambda:[0,0])  # omega -> [n, SP=1]
    dist=np.zeros(len(U))  # sign-pattern distribution, aggregated over primes (count of primes with P(-1)) computed separately
    Pm1=[]
    for p in primes:
        Nn=4*C*p+1
        pf=factor(Nn)
        res=[q%m for q in pf if math.gcd(q,m)==1]
        assert len(res)==len(pf)  # ℓ | N is coprime to 4C
        # SP: subset products of distinct residues (nonempty)
        R=set()
        for r in res:
            new={r}|{(x*r)%m for x in R}
            R|=new
        sp = (m-1)%m in R if m>2 else (1 in R)
        gen = (m-1)%m in gen_closure(res,m) if m>2 else True
        w=len(pf)
        omegas[w][0]+=1; omegas[w][1]+=int(sp)
        cnt['n']+=1; cnt['sp']+=int(sp); cnt['gen']+=int(gen); cnt['gen_not_sp']+=int(gen and not sp); cnt['sp_not_gen']+=int(sp and not gen)
        # Z2589 DP over sign patterns
        if m>2:
            vec=np.zeros(len(U)); vec[idx[1]]=1.0
            for r in res:
                ri=idx[r]; ri_inv=idx[pow(r,-1,m)]
                nv=vec.copy()
                # multiply by r or r^{-1}
                for ui,u in enumerate(U):
                    if vec[ui]:
                        nv[idx[(u*r)%m]]+=vec[ui]; nv[idx[(u*pow(r,-1,m))%m]]+=vec[ui]
                vec=nv
            tot=vec.sum()
            Pm1.append(vec[idx[m-1]]/tot)
            dist+=vec/tot
    stats[C]=dict(m=m,phi=len(U),n=cnt['n'],sp=cnt['sp']/cnt['n'],gen=cnt['gen']/cnt['n'],gen_not_sp=cnt['gen_not_sp'],sp_not_gen=cnt['sp_not_gen'],
                  Pm1_mean=float(np.mean(Pm1)) if Pm1 else None, unif=1/len(U), omega={w:(v[0],round(v[1]/v[0],3)) for w,v in sorted(omegas.items()) if v[0]>0})
    s=stats[C]
    print(f"C={C:2d} m=4C={m:3d} phi={s['phi']:2d} n={s['n']} SP={s['sp']:.4f} GEN={s['gen']:.4f} gen&!sp={s['gen_not_sp']} sp&!gen={s['sp_not_gen']} P(-1| signs)={s['Pm1_mean']:.4f} vs 1/phi={s['unif']:.4f}", flush=True)
print("time",round(time.time()-t0,1))
import json
json.dump({str(k):v for k,v in stats.items()}, open('data/z52b/pass2/TO7/zs_summary.json','w'), indent=1, default=str)
